import { closeSync, lstatSync, openSync, readdirSync, readSync, statSync } from "node:fs";
import { realpathSync } from "node:fs";
import { dirname, isAbsolute, join, normalize, relative, resolve, sep } from "node:path";

/**
 * Provenance values understood by the workspace-external write boundary.
 *
 * `trusted-system` and `direct-operator` are the only values which permit a
 * write outside the workspace.  The remaining values are deliberately
 * conservative: an unknown or malformed provenance is never trusted.
 */
export type WorkspaceExternalWriteProvenance =
  | "trusted-system"
  | "direct-operator"
  | "external"
  | "derived"
  | "invalid"
  | "missing"
  | "trusted_system"
  | "direct_operator"
  | "external"
  | "derived"
  | "invalid"
  | "missing";

export type WorkspaceExternalWriteProvenanceInput =
  | WorkspaceExternalWriteProvenance
  | null
  | undefined
  | {
      readonly kind?: WorkspaceExternalWriteProvenance | string | null;
      readonly source?: WorkspaceExternalWriteProvenance | string | null;
      readonly provenance?: WorkspaceExternalWriteProvenance | string | null;
    };

export interface WorkspaceExternalWritePolicyInput {
  readonly provenance: WorkspaceExternalWriteProvenanceInput;
  readonly targetPath: string;
  readonly workspaceRoot: string;
}

export interface WorkspaceExternalWritePolicyResult {
  readonly allowed: boolean;
  readonly external: boolean;
  readonly trusted: boolean;
  readonly reason:
    | "in-workspace"
    | "trusted-external-write"
    | "untrusted-external-write"
    | "invalid-target"
    | "invalid-workspace-root";
  /** UNC and device-namespace behavior cannot be proven on every host. */
  readonly residual?: "unc-or-device-namespace";
}

export class WorkspaceExternalWritePolicyError extends Error {
  readonly code = "WORKSPACE_EXTERNAL_WRITE_FORBIDDEN";
  readonly result: WorkspaceExternalWritePolicyResult;

  constructor(result: WorkspaceExternalWritePolicyResult, message?: string) {
    super(
      message ??
        `Refusing to write outside the workspace with untrusted provenance (${result.reason}).`,
    );
    this.name = "WorkspaceExternalWritePolicyError";
    this.result = result;
  }
}

const TRUSTED_PROVENANCE = new Set(["trusted-system", "trusted_system", "direct-operator", "direct_operator"]);
const KNOWN_UNTRUSTED_PROVENANCE = new Set(["external", "derived", "invalid", "missing"]);

function provenanceValue(
  provenance: WorkspaceExternalWriteProvenanceInput,
): WorkspaceExternalWriteProvenance | "unknown" {
  if (typeof provenance === "string") {
    return provenance as WorkspaceExternalWriteProvenance;
  }
  if (!provenance || typeof provenance !== "object") {
    return "unknown";
  }
  const value = provenance.kind ?? provenance.source ?? provenance.provenance;
  return typeof value === "string" ? (value as WorkspaceExternalWriteProvenance) : "unknown";
}

function isTrustedProvenance(provenance: WorkspaceExternalWriteProvenanceInput): boolean {
  return TRUSTED_PROVENANCE.has(provenanceValue(provenance));
}

function isInside(root: string, candidate: string): boolean {
  const rootPath = normalize(root);
  const candidatePath = normalize(candidate);
  if (isAbsolute(rootPath) && isAbsolute(candidatePath)) {
    const rootComparable = process.platform === "win32" ? rootPath.toLowerCase() : rootPath;
    const candidateComparable = process.platform === "win32" ? candidatePath.toLowerCase() : candidatePath;
    const rel = relative(rootComparable, candidateComparable);
    return rel === "" || (!rel.startsWith(`..${sep}`) && rel !== ".." && !isAbsolute(rel));
  }
  const rel = relative(rootPath, candidatePath);
  return rel === "" || (!rel.startsWith(`..${sep}`) && rel !== ".." && !isAbsolute(rel));
}

/**
 * Resolve the longest existing ancestor and append the non-existing suffix.
 * This makes a symlink in any parent component part of the effective target,
 * rather than checking only the lexical path.
 */
function resolveEffectivePath(targetPath: string): string {
  let current = resolve(targetPath);
  const suffix: string[] = [];

  for (;;) {
    try {
      const real = realpathSync.native(current);
      return suffix.length === 0 ? real : resolve(real, ...suffix.reverse());
    } catch {
      const parent = dirname(current);
      if (parent === current) {
        return resolve(targetPath);
      }
      suffix.push(current.slice(parent.length + (current.endsWith(sep) ? 0 : 1)));
      current = parent;
    }
  }
}

function deviceIdentity(path: string): string | undefined {
  try {
    const stat = statSync(path);
    return `${stat.dev}:${stat.ino}`;
  } catch {
    return undefined;
  }
}

function workspaceInodeOutsideRoot(workspaceRoot: string, targetPath: string): boolean {
  const targetIdentity = deviceIdentity(targetPath);
  if (!targetIdentity) {
    return false;
  }

  const visited = new Set<string>();
  const pending = [resolve(workspaceRoot)];
  while (pending.length > 0) {
    const current = pending.pop()!;
    let realCurrent: string;
    try {
      realCurrent = realpathSync.native(current);
    } catch {
      continue;
    }
    if (visited.has(realCurrent)) {
      continue;
    }
    visited.add(realCurrent);

    if (deviceIdentity(realCurrent) === targetIdentity && !isInside(workspaceRoot, realCurrent)) {
      return true;
    }

    let entries;
    try {
      entries = readdirSync(realCurrent, { withFileTypes: true });
    } catch {
      continue;
    }
    for (const entry of entries) {
      const child = join(realCurrent, entry.name);
      if (entry.isDirectory()) {
        pending.push(child);
      } else if (deviceIdentity(child) === targetIdentity && !isInside(workspaceRoot, child)) {
        return true;
      }
    }
  }
  return false;
}

function hasNonExistingSuffix(targetPath: string): boolean {
  let current = resolve(targetPath);
  for (;;) {
    try {
      lstatSync(current);
      return false;
    } catch {
      const parent = dirname(current);
      if (parent === current) {
        return true;
      }
      current = parent;
    }
  }
}

function isUncertainNamespace(targetPath: string): boolean {
  if (process.platform !== "win32") {
    return false;
  }
  return /^(?:\\\\|\/\/)/.test(targetPath) || /^[a-zA-Z]:[?*]/.test(targetPath);
}

function evaluate(input: WorkspaceExternalWritePolicyInput): WorkspaceExternalWritePolicyResult {
  if (!input || typeof input.targetPath !== "string" || input.targetPath.length === 0) {
    return { allowed: false, external: false, trusted: false, reason: "invalid-target" };
  }
  if (typeof input.workspaceRoot !== "string" || input.workspaceRoot.length === 0) {
    return { allowed: false, external: false, trusted: false, reason: "invalid-workspace-root" };
  }

  const workspaceRoot = resolve(input.workspaceRoot);
  const effectiveTarget = resolveEffectivePath(input.targetPath);
  const effectiveRoot = resolveEffectivePath(workspaceRoot);
  const lexicalTarget = resolve(input.targetPath);
  const external = !isInside(effectiveRoot, effectiveTarget) || !isInside(workspaceRoot, lexicalTarget);
  const trusted = isTrustedProvenance(input.provenance);

  if (!external) {
    return { allowed: true, external: false, trusted, reason: "in-workspace" };
  }
  if (trusted) {
    return { allowed: true, external: true, trusted: true, reason: "trusted-external-write" };
  }

  const aliasOutside = workspaceInodeOutsideRoot(workspaceRoot, effectiveTarget);
  const uncertain = isUncertainNamespace(input.targetPath);
  return {
    allowed: false,
    external: true,
    trusted: false,
    reason: aliasOutside ? "untrusted-external-write" : "untrusted-external-write",
    ...(uncertain ? { residual: "unc-or-device-namespace" as const } : {}),
  };
}

/** Evaluate the boundary without performing any filesystem mutation. */
export function evaluateWorkspaceExternalWritePolicy(
  input: WorkspaceExternalWritePolicyInput,
): WorkspaceExternalWritePolicyResult {
  return evaluate(input);
}

export const evaluateWorkspaceExternalWrite = evaluateWorkspaceExternalWritePolicy;

/**
 * Throw before a caller performs write/edit/apply_patch filesystem operations.
 * The function intentionally has no file-system side effects.
 */
export function assertWorkspaceExternalWriteAllowed(
  input: WorkspaceExternalWritePolicyInput,
): WorkspaceExternalWritePolicyResult {
  const result = evaluate(input);
  if (!result.allowed) {
    throw new WorkspaceExternalWritePolicyError(result);
  }
  return result;
}

export const assertWorkspaceExternalWrite = assertWorkspaceExternalWriteAllowed;\nexport const assertExternalWriteAllowed = assertWorkspaceExternalWriteAllowed;

export function isWorkspaceExternalWriteAllowed(
  input: WorkspaceExternalWritePolicyInput,
): boolean {
  return evaluate(input).allowed;
}

export function isTrustedExternalWriteProvenance(
  provenance: WorkspaceExternalWriteProvenanceInput,
): boolean {
  return isTrustedProvenance(provenance);
}

export function isKnownUntrustedExternalWriteProvenance(
  provenance: WorkspaceExternalWriteProvenanceInput,
): boolean {
  return KNOWN_UNTRUSTED_PROVENANCE.has(provenanceValue(provenance));
}

export default assertWorkspaceExternalWriteAllowed;

